package com.finsightai.controller; import com.finsightai.dto.*;import com.finsightai.service.AuthService;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/auth") public class AuthController{private final AuthService service;public AuthController(AuthService s){service=s;}@PostMapping("/login")public AuthResponse login(@Valid @RequestBody AuthRequest r){return service.login(r);}}
